// GroupByParam groups by the given page parameter key's value and with the given order.
// Valid values for order is asc, desc, rev and reverse.
func (p Pages) GroupByParam(key string, order ...string) (PagesGroup, error) {
	if len(p) < 1 {
		return nil, nil
	}

	direction := "asc"
	if len(order) > 0 {
		normalizedOrder := strings.ToLower(order[0])
		switch normalizedOrder {
		case "desc", "rev", "reverse":
			direction = "desc"
		}
	}

	paramKey := strings.ToLower(key)
	var tmp reflect.Value
	var keyt reflect.Type
	for _, e := range p {
		values := e.Params()
		var param any
		if values != nil {
			raw := values[paramKey]
			if raw != nil {
				switch val := raw.(type) {
				case bool, time.Time, map[string]any, map[any]any:
					param = val
				case string:
					param = strings.ToLower(val)
				case int64, int32, int16, int8, int:
					param = cast.ToInt(raw)
				case float64, float32:
					param = cast.ToFloat64(raw)
				case toml.LocalDate:
					param = val.AsTime(time.UTC)
				case toml.LocalDateTime:
					param = val.AsTime(time.UTC)
				case []string:
					if val != nil {
						lowered := make([]string, len(val))
						for i, item := range val {
							lowered[i] = strings.ToLower(item)
						}
						param = lowered
					} else {
						param = helpers.SliceToLower(val)
					}
				}
			}
		}
		if param != nil {
			if _, isStringSlice := param.([]string); !isStringSlice {
				keyt = reflect.TypeOf(param)
				mapType := reflect.MapOf(keyt, pagesType)
				tmp = reflect.MakeMap(mapType)
				break
			}
		}
	}
	if !tmp.IsValid() {
		return nil, errors.New("there is no such param")
	}

	for _, e := range p {
		values := e.Params()
		var param any
		raw := values[paramKey]
		switch val := raw.(type) {
		case bool, time.Time, map[string]any, map[any]any:
			param = val
		case string:
			param = val
		case int64, int32, int16, int8, int:
			param = cast.ToInt(raw)
		case float64, float32:
			param = cast.ToFloat64(raw)
		case toml.LocalDate:
			param = val.AsTime(time.UTC)
		case toml.LocalDateTime:
			param = val.AsTime(time.UTC)
		case []string:
			param = val
		}
		if reflect.TypeOf(param) != keyt {
			continue
		}
		v := reflect.ValueOf(param)
		grouped := tmp.MapIndex(v)
		if !grouped.IsValid() {
			grouped = reflect.MakeSlice(pagesType, 0, 0)
			tmp.SetMapIndex(v, grouped)
		}
		pageValue := reflect.ValueOf(e)
		updated := reflect.Append(tmp.MapIndex(v), pageValue)
		tmp.SetMapIndex(v, updated)
	}

	keys := tmp.MapKeys()
	if len(keys) > 1 {
		switch keys[0].Kind() {
		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
			if direction == "desc" {
				sort.Sort(sort.Reverse(mapKeyByInt{keys}))
			} else {
				sort.Sort(mapKeyByInt{keys})
			}
		case reflect.String:
			examplePage := p[0]
			currentSite := examplePage.Site()
			renderedSite := currentSite.Current()
			language := renderedSite.Language()
			coll := langs.GetCollator2(language)
			coll.Lock()
			less := func(s1, s2 string) bool {
				return coll.CompareStrings(s1, s2) < 1
			}
			if direction == "desc" {
				sort.Sort(sort.Reverse(mapKeyByStr{less, keys}))
			} else {
				sort.Sort(mapKeyByStr{less, keys})
			}
			coll.Unlock()
		}
	}

	var r []PageGroup
	for _, k := range keys {
		grouped := tmp.MapIndex(k)
		pagesInGroup := grouped.Interface().(Pages)
		groupKey := k.Interface()
		r = append(r, PageGroup{Key: groupKey, Pages: pagesInGroup})
	}

	return r, nil
}

func (p Pages) groupByDateField(format string, sorter func(p Pages) Pages, getDate func(p Page) time.Time, order ...string) (PagesGroup, error) {
	if len(p) < 1 {
		return nil, nil
	}

	sp := sorter(p)

	if !(len(order) > 0 && (strings.ToLower(order[0]) == "asc" || strings.ToLower(order[0]) == "rev" || strings.ToLower(order[0]) == "reverse")) {
		sp = sp.Reverse()
	}

	if sp == nil {
		return nil, nil
	}

	firstPage := sp[0]
	date := getDate(firstPage)

	// Pages may be a mix of multiple languages, so we need to use the language
	// for the currently rendered Site.
	currentSite := firstPage.Site().Current()
	formatter := langs.GetTimeFormatter(currentSite.Language())
	formatted := formatter.Format(date, format)
	var r []PageGroup
	r = append(r, PageGroup{Key: formatted, Pages: make(Pages, 0)})
	r[0].Pages = append(r[0].Pages, sp[0])

	i := 0
	for _, e := range sp[1:] {
		date = getDate(e)
		formatted := formatter.Format(date, format)
		if r[i].Key.(string) != formatted {
			r = append(r, PageGroup{Key: formatted})
			i++
		}
		r[i].Pages = append(r[i].Pages, e)
	}
	return r, nil
}

